import "./helpers/leak_guard.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs"; import os from "node:os"; import path from "node:path";
import { PluginManager, workspacePluginTrustId, pluginFileSha256 } from "../src/plugins.js";
import { approveExtension } from "../src/core/content_trust.js";
import { setWorkspaceTrusted } from "../src/workspace_trust.js";
import { policyWorld, toml } from "./helpers/policy_enforcement.js";
test("probe policy", async () => {
  const home = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "pp-h-"))); const ws = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "pp-w-")));
  process.env.HOME = home; process.env.XDG_CONFIG_HOME = path.join(home, ".config");
  setWorkspaceTrusted(ws, true);
  const f = path.join(ws, ".nexus/plugins/p.mjs"); fs.mkdirSync(path.dirname(f), { recursive: true });
  const m = path.join(home, "m"); fs.writeFileSync(f, `import fs from "node:fs"; fs.writeFileSync(${JSON.stringify(m)},"x");\nexport default {name:"p",description:"d"};`);
  const h = pluginFileSha256(f); const id = workspacePluginTrustId(ws, f);
  const approve = () => approveExtension({ kind: "workspace-plugin", scope: id.scope, key: id.key, sha256: h, approvedAt: "x", summary: "p" });
  const run = async (sys: string | undefined) => { fs.rmSync(m, { force: true }); const pm = new PluginManager(ws, { policy: () => policyWorld({ system: sys }).host.managed().effective }); await pm.loadPlugins(); return { ran: fs.existsSync(m), st: pm.getPluginTrustRecords().map((r) => r.status).join() }; };
  console.log("unapproved, allow lists hash:", JSON.stringify(await run(toml("[plugins]", `allow = ["sha256:${h}"]`))));
  approve();
  console.log("approved, no policy:", JSON.stringify(await run(undefined)));
  console.log("approved, disable_workspace:", JSON.stringify(await run(toml("[plugins]", "disable_workspace = true"))));
  console.log("approved, allow other hash:", JSON.stringify(await run(toml("[plugins]", `allow = ["sha256:${"0".repeat(64)}"]`))));
  console.log("approved, allow this hash:", JSON.stringify(await run(toml("[plugins]", `allow = ["sha256:${h}"]`))));
  console.log("approved, allow=[] :", JSON.stringify(await run(toml("[plugins]", "allow = []"))));
});
EOF
HOME=$(mktemp -d) TMPDIR=/dev/shm rtk proxy node --import tsx --test test/zz_probe_policy.test.ts 2>&1 | grep -E "^(unapproved|approved)|^. (pass|fail)|Error" | head

